328	  async function handleProjectWorkspaceRuntimeCommand(req: Request, res: Response) {
329	    const id = req.params.id as string;
330	    const workspaceId = req.params.workspaceId as string;
331	    const action = String(req.params.action ?? "").trim().toLowerCase();
332	    if (action !== "start" && action !== "stop" && action !== "restart" && action !== "run") {
333	      res.status(404).json({ error: "Workspace command action not found" });
334	      return;
335	    }
336	
337	    const project = await svc.getById(id);
338	    if (!project) {
339	      res.status(404).json({ error: "Project not found" });
340	      return;
341	    }
342	    assertCompanyAccess(req, project.companyId);
343	
344	    const workspace = project.workspaces.find((entry) => entry.id === workspaceId) ?? null;
345	    if (!workspace) {
346	      res.status(404).json({ error: "Project workspace not found" });
347	      return;
348	    }
349	
350	    const isSharedWorkspace = Boolean(workspace.sharedWorkspaceKey);
351	    if (
352	      req.actor.type === "agent"
353	      && isSharedWorkspace
354	      && SHARED_WORKSPACE_STOP_AND_RESTART_ACTIONS.has(action)
355	    ) {
356	      throw forbidden("Missing permission to manage workspace runtime services");
357	    }
358	
359	    await assertCanManageProjectWorkspaceRuntimeServices(db, req, {
360	      companyId: project.companyId,
361	      projectWorkspaceId: workspace.id,
362	    });
363	
364	    const workspaceCwd = workspace.cwd;
365	    if (!workspaceCwd) {
366	      res.status(422).json({ error: "Project workspace needs a local path before Paperclip can run workspace commands" });
367	      return;
368	    }
369	
370	    const runtimeConfig = workspace.runtimeConfig?.workspaceRuntime ?? null;
371	    const target = req.body as { workspaceCommandId?: string | null; runtimeServiceId?: string | null; serviceIndex?: number | null };
372	    const configuredServices = runtimeConfig ? listConfiguredRuntimeServiceEntries({ workspaceRuntime: runtimeConfig }) : [];
373	    const workspaceCommand = runtimeConfig
374	      ? findWorkspaceCommandDefinition(runtimeConfig, target.workspaceCommandId ?? null)
375	      : null;
376	    if (target.workspaceCommandId && !workspaceCommand) {
377	      res.status(404).json({ error: "Workspace command not found for this project workspace" });
378	      return;
379	    }
380	    if (target.runtimeServiceId && !(workspace.runtimeServices ?? []).some((service) => service.id === target.runtimeServiceId)) {
381	      res.status(404).json({ error: "Runtime service not found for this project workspace" });
382	      return;
383	    }
384	    const matchedRuntimeService =
385	      workspaceCommand?.kind === "service" && !target.runtimeServiceId
386	        ? matchWorkspaceRuntimeServiceToCommand(workspaceCommand, workspace.runtimeServices ?? [])
387	        : null;
388	    const selectedRuntimeServiceId = target.runtimeServiceId ?? matchedRuntimeService?.id ?? null;
389	    const selectedServiceIndex =
390	      workspaceCommand?.kind === "service"
391	        ? workspaceCommand.serviceIndex
392	        : target.serviceIndex ?? null;
393	    if (
394	      selectedServiceIndex !== undefined
395	      && selectedServiceIndex !== null
396	      && (selectedServiceIndex < 0 || selectedServiceIndex >= configuredServices.length)
397	    ) {
398	      res.status(422).json({ error: "Selected runtime service is not defined in this project workspace runtime config" });
399	      return;
400	    }
401	    if (workspaceCommand?.kind === "job" && action !== "run") {
402	      res.status(422).json({ error: `Workspace job "${workspaceCommand.name}" can only be run` });
403	      return;
404	    }
405	    if (workspaceCommand?.kind === "service" && action === "run") {
406	      res.status(422).json({ error: `Workspace service "${workspaceCommand.name}" should be started or restarted, not run` });
407	      return;
408	    }
409	    if (action === "run" && !workspaceCommand) {
410	      res.status(422).json({ error: "Select a workspace job to run" });
411	      return;
412	    }
413	    if ((action === "start" || action === "restart") && !runtimeConfig) {
414	      res.status(422).json({ error: "Project workspace has no workspace command configuration" });
415	      return;
416	    }
417	
418	    const actor = getActorInfo(req);
419	    const recorder = workspaceOperations.createRecorder({ companyId: project.companyId });
420	    let runtimeServiceCount = workspace.runtimeServices?.length ?? 0;
421	    let stdout = "";
422	    let stderr = "";
423	
424	    const operation = await recorder.recordOperation({
425	      phase: action === "stop" ? "workspace_teardown" : "workspace_provision",
426	      command: workspaceCommand?.command ?? `workspace command ${action}`,
427	      cwd: workspace.cwd,
428	      metadata: {
429	        action,
430	        projectId: project.id,
431	        projectWorkspaceId: workspace.id,
432	        workspaceCommandId: workspaceCommand?.id ?? target.workspaceCommandId ?? null,
433	        workspaceCommandKind: workspaceCommand?.kind ?? null,
434	        workspaceCommandName: workspaceCommand?.name ?? null,
435	        runtimeServiceId: selectedRuntimeServiceId,
436	        serviceIndex: selectedServiceIndex,
437	      },
438	      run: async () => {
439	        if (action === "run") {
440	          if (!workspaceCommand || workspaceCommand.kind !== "job") {
441	            throw new Error("Workspace job selection is required");
442	          }
443	          return await runWorkspaceJobForControl({
444	            actor: {
445	              id: actor.agentId ?? null,
446	              name: actor.actorType === "user" ? "Board" : "Agent",
447	              companyId: project.companyId,
448	            },
449	            issue: null,
450	            workspace: {
451	              baseCwd: workspaceCwd,
452	              source: "project_primary",
453	              projectId: project.id,
454	              workspaceId: workspace.id,
455	              repoUrl: workspace.repoUrl,
456	              repoRef: workspace.repoRef,
457	              strategy: "project_primary",
458	              cwd: workspaceCwd,
459	              branchName: workspace.defaultRef ?? workspace.repoRef ?? null,
460	              worktreePath: null,
461	              warnings: [],
462	              created: false,
463	            },
464	            command: workspaceCommand.rawConfig,
465	            adapterEnv: {},
466	            recorder,
467	            metadata: {
468	              action,
469	              projectId: project.id,
470	              projectWorkspaceId: workspace.id,
471	              workspaceCommandId: workspaceCommand.id,
472	            },
473	          }).then((nestedOperation) => ({
474	            status: "succeeded" as const,
475	            exitCode: 0,
476	            metadata: {
477	              nestedOperationId: nestedOperation?.id ?? null,
478	              runtimeServiceCount,
479	            },
480	          }));
481	        }
482	
483	        const onLog = async (stream: "stdout" | "stderr", chunk: string) => {
484	          if (stream === "stdout") stdout = appendWithCap(stdout, chunk, WORKSPACE_CONTROL_OUTPUT_MAX_CHARS);
485	          else stderr = appendWithCap(stderr, chunk, WORKSPACE_CONTROL_OUTPUT_MAX_CHARS);
486	        };
487	
488	        if (action === "stop" || action === "restart") {
489	          await stopRuntimeServicesForProjectWorkspace({
490	            db,
491	            projectWorkspaceId: workspace.id,
492	            runtimeServiceId: selectedRuntimeServiceId,
493	          });
494	        }
495	
496	        if (action === "start" || action === "restart") {
497	          const startedServices = await startRuntimeServicesForWorkspaceControl({
498	            db,
499	            actor: {
500	              id: actor.agentId ?? null,
501	              name: actor.actorType === "user" ? "Board" : "Agent",
502	              companyId: project.companyId,
503	            },
504	            issue: null,
505	            workspace: {
506	              baseCwd: workspaceCwd,
507	              source: "project_primary",
